def solve(retrieved, relevant):
    ranked=list(dict.fromkeys(retrieved))
    relevant=set(relevant)
    hits=set(ranked)&relevant
    rr=next((1/(i+1) for i,key in enumerate(ranked) if key in relevant),0)
    return dict(recall=len(hits)/len(relevant) if relevant else None,reciprocal_rank=rr)
